using System;
using System.IO;
using System.Reflection;
using System.Collections.Generic;
using System.Web.Script.Serialization;

// Runtime predicate replay against a license generated by the OpenCode tool.
// Original methods 0x06000913 / 0x0600090D / 0x0600066B / loader 0x060006CA.
// No Main/UI execution, no database/network I/O; guard 0x04000343 keeps the
// online path short-circuited. Usage: Runtime913Probe.exe <licensePath> <outdir> <outJson>
public static class Runtime913Probe {
    static string Root = Path.Combine(Path.GetTempPath(), "opencode");
    static Module module;
    static object Call(int token, params object[] args) {
        return ((MethodInfo)module.ResolveMethod(token)).Invoke(null, args);
    }
    static void Set(int token, object value) { module.ResolveField(token).SetValue(null, value); }
    static object Get(int token) { return module.ResolveField(token).GetValue(null); }
    static string Within(string p) {
        p = Path.GetFullPath(p);
        if (!p.StartsWith(Root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
            throw new Exception("Outside opencode sandbox");
        return p;
    }
    static long Minute(DateTime d) { return (long)Call(0x0600066B, d); }

    static Dictionary<string, object> Check(string name, string db, string system,
        int count, DateTime now, string client) {
        Set(0x040004D6, false); Set(0x040004DF, false); Set(0x040004E0, true);
        Set(0x040004D7, count); Set(0x040004DB, db); Set(0x040004E7, system);
        Set(0x040004DC, Minute(now)); Set(0x040004EE, client); Set(0x040004DA, false);
        Set(0x0400033D, 0); Set(0x04000343, true);
        Set(0x040004D8, ""); Set(0x040004D9, -999);
        Call(0x06000913, new object[] { null });
        bool active = (bool)Call(0x0600090D);
        return new Dictionary<string, object> {
            {"scenario", name}, {"current_database_id", db}, {"current_system_id", system},
            {"active_face_count", count}, {"database_time_simulated", now.ToString("s")},
            {"original_predicate_90D", active}, {"original_active_flag_4DA", Get(0x040004DA)},
            {"status_code", Get(0x040004D9)}, {"status_text", Get(0x040004D8)},
            {"online_state", Get(0x0400033D)}, {"db_connected_injected", false},
            {"server_running_injected", true}, {"online_start_guard_injected", true}
        };
    }

    static int Main(string[] args) {
        try {
            string source = Within(args[0]), outdir = Within(args[1]);
            Directory.CreateDirectory(outdir);
            Environment.CurrentDirectory = outdir;
            string targetDir = @"C:\Program Files\YIM\JIBAS Face Server 16.5";
            AppDomain.CurrentDomain.AssemblyResolve += delegate(object s, ResolveEventArgs ev) {
                string p = Path.Combine(targetDir, new AssemblyName(ev.Name).Name + ".dll");
                return File.Exists(p) ? Assembly.LoadFrom(p) : null;
            };
            Assembly asm = Assembly.LoadFile(Path.Combine(targetDir, "FaceServer.exe"));
            module = asm.ManifestModule;
            Set(0x04000395, outdir); Call(0x060006C5); Call(0x060006C4);
            File.Copy(source, Path.Combine(outdir, "license.enc"), true);
            bool loaded = (bool)Call(0x060006CA);
            if (!loaded) throw new Exception("Original CA loader rejected runtime license");
            string licDb = (string)Get(0x040004F0), licSys = (string)Get(0x040004F8);
            string licClient = (string)Get(0x040004EE);
            int max = (int)Get(0x040004F5); DateTime expires = (DateTime)Get(0x040004F3);
            DateTime now = new DateTime(2026, 11, 10, 12, 0, 0);
            var cases = new List<Dictionary<string, object>>();
            cases.Add(Check("valid", licDb, licSys, 0, now, licClient));
            cases.Add(Check("wrong_database", "ZZZZZ", licSys, 0, now, licClient));
            cases.Add(Check("wrong_system", licDb, "ZZZZZ", 0, now, licClient));
            cases.Add(Check("system_id_of_cached_ddcb4", licDb, "DDCB4", 0, now, licClient));
            cases.Add(Check("expired", licDb, licSys, 0, expires.AddYears(1), licClient));
            cases.Add(Check("at_capacity", licDb, licSys, max, now, licClient));
            cases.Add(Check("over_capacity", licDb, licSys, max + 1, now, licClient));
            cases.Add(Check("trial", licDb, licSys, 0, now, "TRIAL"));
            bool ok = (bool)cases[0]["original_predicate_90D"]
                && !(bool)cases[1]["original_predicate_90D"]
                && !(bool)cases[2]["original_predicate_90D"]
                && !(bool)cases[3]["original_predicate_90D"]
                && !(bool)cases[4]["original_predicate_90D"]
                && (bool)cases[5]["original_predicate_90D"]
                && !(bool)cases[6]["original_predicate_90D"]
                && !(bool)cases[7]["original_predicate_90D"];
            var result = new Dictionary<string, object> {
                {"artifact_sha256", "8a123015b2ee095ceda51ece6d47436e9760c88be8f92fb76ed7c120c923c364"},
                {"test_kind", "controlled original-method replay with simulated environment; not production activation"},
                {"original_loader_CA_accepted", loaded}, {"source", source},
                {"license_database_id", licDb}, {"license_system_id_Info1", licSys},
                {"license_max_client", max}, {"license_expires", expires.ToString("s")},
                {"cases", cases}, {"all_expected_outcomes", ok},
                {"execution_boundary", "No Main/UI execution or database/network I/O performed. Gate wrappers 910/780 returned before SQL or Task.Run because DB-connected=false and online-start guard 0x04000343=true. Binary is unmodified."}
            };
            string json = new JavaScriptSerializer().Serialize(result);
            File.WriteAllText(Within(args[2]), json, new System.Text.UTF8Encoding(false));
            foreach (var item in cases)
                Console.WriteLine(item["scenario"] + ": " + item["original_predicate_90D"] + "; " + item["status_text"]);
            Console.WriteLine("All expected outcomes: " + ok);
            return ok ? 0 : 2;
        } catch (Exception ex) {
            while (ex.InnerException != null) ex = ex.InnerException;
            Console.Error.WriteLine(ex);
            return 1;
        }
    }
}
